mapper.select:
SELECT p.productCode, p.productName, p.displayMode, p.highlight, p.category, p.price, p.stock, IFNULL(SUM(od.purchaseNum), 0) AS sales, p.create_time FROM cultural_product p LEFT JOIN orderDetails od ON od.productCode = p.productCode
p.is_deleted = 0
AND BINARY p.productCode = #{productCode}
AND p.productCode like concat('%', #{productCode}, '%')
AND BINARY p.productName = #{productName}
AND p.productName like concat('%', #{productName}, '%')
AND BINARY p.displayMode = #{displayMode}
AND p.displayMode like concat('%', #{displayMode}, '%')
AND BINARY p.highlight = #{highlight}
AND p.highlight like concat('%', #{highlight}, '%')
AND (
FIND_IN_SET(BINARY #{cat}, REPLACE(REPLACE(p.category,'、', ','),'，',','))
FIND_IN_SET(#{cat}, REPLACE(REPLACE(p.category,'、', ','),'，',','))
)
AND BINARY p.category = #{category}
AND p.category like concat('%', #{category}, '%')
AND p.price BETWEEN #{minPrice} AND #{maxPrice}
AND p.stock BETWEEN #{minStock} AND #{maxStock}
GROUP BY p.productCode, p.productName, p.displayMode, p.highlight, p.category, p.price, p.stock, p.create_time

mapper.update:
UPDATE cultural_product
SET stock = stock - #{quantity}
WHERE productCode = #{productCode}

UPDATE cultural_product
SET stock = stock + #{quantity}
WHERE productCode = #{productCode}
